package com.dy.artisan3d.ui.componentimport androidx.compose.foundation.layout.WindowInsetsimport androidx.compose.foundation.layout.statusBarsimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.Textimport androidx.compose.material3.TopAppBarimport androidx.compose.runtime.Composableimport androidx.compose.ui.text.style.TextOverflowimport com.dy.artisan3d.isAndroidPlatform@OptIn(ExperimentalMaterial3Api::class)@Composablefun Topbar(    title: String,    onNavigationIcon: @Composable () -> Unit = {},    onActionBar: @Composable () -> Unit = {},) {    TopAppBar(        title = {            Text(                text = title,                maxLines = 1,                overflow = TextOverflow.Ellipsis            )        },        navigationIcon = {            onNavigationIcon()        },        actions = {            onActionBar()        },        windowInsets = if (isAndroidPlatform()) WindowInsets.statusBars else WindowInsets(            0,            0,            0,            0        )    )}